/**
 * MailerLite Node - Version 2
 * Discriminator: resource=subscriber, operation=getAll
 */


interface Credentials {
  mailerLiteApi: CredentialReference;
}

/** Get many subscribers */
export type MailerLiteV2SubscriberGetAllParams = {
  resource: 'subscriber';
  operation: 'getAll';
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 50
 */
    limit?: number | Expression<number>;
/**
 * Filters
 * @default {}
 */
    filters?: {
    /** Status
     */
    status?: 'active' | 'bounced' | 'junk' | 'unconfirmed' | 'unsubscribed' | Expression<string>;
  };
};

export type MailerLiteV2SubscriberGetAllOutput = {
  id: number;
  name: string;
  email: string;
  sent: number;
  opened: number;
  clicked: number;
  type: string;
  country_id: string;
  signup_ip: null;
  signup_timestamp: null;
  confirmation_ip: null;
  confirmation_timestamp: null;
  fields: Array<{
    key: string;
    value: string;
    type: string;
  }>;
  date_subscribe: string;
  date_created: string;
  date_updated: string;
};

export type MailerLiteV2SubscriberGetAllNode = {
  type: 'n8n-nodes-base.mailerLite';
  version: 2;
  config: NodeConfig<MailerLiteV2SubscriberGetAllParams> & { credentials?: Credentials };
  output?: Items<MailerLiteV2SubscriberGetAllOutput>;
};